        requestId: str,
        tabId: str,
        pageRevision: int,
        summary: str,
        actions: list[PlanAction],
        confidence: str,
        warnings: list[str],
        suggestedScope: str,
        status: str;
}

obj BrowserCommand {
    has schemaVersion: int,
        requestId: str,
        tabId: str,
        kind: str,
        arguments: dict[str, any],
        requiresConfirmation: bool;
}

obj StructuredError {
    has requestId: str,
        code: str,
        message: str,
        retryable: bool,
